import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def feature_pairs(ctx):
    inputs = torch.randn(6, generator=ctx.rng.torch)
    teacher_features = torch.randn(3, 2, 2, generator=ctx.rng.torch)
    return {"inputs": synth.Tensor(inputs), "teacher_features": synth.Tensor(teacher_features)}
dataset = synth.Spec("attention-transfer", generator=feature_pairs, size=8, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = dataset.for_recipe("structured-objective", split="train")
class Student(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=6, out_features=12)
    def forward(self, inputs):
        return {"student_features": self.network(inputs).reshape(-1, 3, 2, 2)}
model = Student()
trainer = Trainer(model, train, recipe="structured-objective", recipe_config={"loss": "attention-transfer", "loss_kwargs": {"beta": 1.0}, "bindings": {"logits_or_prediction": {"output": "student_features"}, "targets": {"batch": "teacher_features"}}}, batch_size=4, max_epochs=1, device="cpu")
