root = tempfile.mkdtemp()
@synth.generator
def coordinates(ctx):
    point = torch.rand(2, generator=ctx.rng.torch) * 2 - 1
    return {"inputs": synth.Tensor(point), "targets": synth.Tensor(torch.zeros(2))}
dataset = synth.Spec("eikonal-coordinates", generator=coordinates, size=4, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
