class GradientField(nn.Module):
    def __init__(self):
        super().__init__()
        self.field = build("mlp", "tiny", in_features=2, out_features=1)
    def forward(self, coordinates):
        coordinates = coordinates.detach().requires_grad_(True)
        values = self.field(coordinates)
        gradients = torch.autograd.grad(values.sum(), coordinates, create_graph=True)[0]
        return {"gradients": gradients}
trainer = Trainer(GradientField(), train, recipe="structured-objective", recipe_config={"loss": "eikonal-sdf", "loss_kwargs": {"lambda_eikonal": 0.1}, "bindings": {"logits_or_prediction": {"output": "gradients"}, "targets": {"batch": "targets"}}}, batch_size=2, max_epochs=1, device="cpu")
